/* ===================== BÀI 12 · Bảng dữ liệu và vùng nhớ ===================== */
/* Bài 12 · Bảng dữ liệu và vùng nhớ (AMTS-EMB-002-M03-L04, X86-012) — sinh bởi tools/author/mpu8086/l12.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P12=[{"label": "Ví dụ: độ lệch phần tử byte và word", "code": "; Ví dụ 1: độ lệch phần tử = đầu bảng + chỉ số × kích thước\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbangB   DB      10, 20, 30, 40          ; 0000h…0003h\nbangW   DW      1000, 2000, 3000, 4000  ; 0004h…000Bh\nnW      EQU     ($ - bangW) / 2         ; số phần tử: 8 / 2 = 4\nkqW     DW      ?                       ; 000Ch\nsoPT    DW      ?                       ; 000Eh\nkqB     DB      ?                       ; 0010h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, 3                   ; phần tử byte thứ 3\n        MOV     AL, bangB[SI]           ; độ lệch 0000h + 3 → 40\n        MOV     kqB, AL\n        MOV     SI, 3 * 2               ; phần tử word thứ 3: chỉ số × 2\n        MOV     AX, bangW[SI]           ; độ lệch 0004h + 6 → 4000\n        MOV     kqW, AX\n        MOV     soPT, nW                ; hằng tính lúc dịch: 4\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước và xem hình địa chỉ vật lý: bangB[SI] có EA 0003h, bangW[SI] với SI = 6 có EA 000Ah; phần Bộ nhớ tô byte 28h và word A0 0F. MOV soPT, nW ghi số 4 do trình dịch tính từ $ − bangW. Đoán trước: sau MOV AX, bangW[SI], AX bằng bao nhiêu (hệ 16)? Đáp án 0FA0h (4000)."}, {"label": "Lỗi: quên nhân 2 với mảng word", "code": "; Lỗi: quên nhân 2 khi lấy phần tử của mảng word\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbangW   DW      1000, 2000, 3000, 4000  ; E8 03 D0 07 B8 0B A0 0F\nkqW     DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, 3                   ; LỖI: phần tử 3 ở độ lệch 6\n        MOV     AX, bangW[SI]           ; đọc byte 3 và 4: 07h, B8h\n        MOV     kqW, AX                 ; kqW = B807h, không phải 4000\n; Sửa: MOV SI, 3 * 2\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi logic có chủ đích: SI = 3 thay vì 6 nên EA = 0003h, lệnh đọc byte cao của phần tử 1 (07h) và byte thấp của phần tử 2 (B8h): AX = B807h. Word ở địa chỉ lẻ còn tốn 21 chu kỳ thay vì 17. Sửa: MOV SI, 3 * 2. Đoán trước: EA của bangW[SI] là bao nhiêu? Đáp án 0003h."}, {"label": "Ví dụ: MOV OFFSET và LEA nạp con trỏ", "code": "; Ví dụ 3: MOV … OFFSET và LEA cùng nạp con trỏ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DB      2 DUP(?)\nbang    DB      'ABCDEFGH'              ; bắt đầu ở 0002h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET bang         ; hằng lúc dịch: 3 byte, 4 ck\n        LEA     DI, bang                ; cùng giá trị: 4 byte, 8 ck\n        MOV     BX, 3\n        LEA     BX, [BX+SI+2]           ; tính EA lúc chạy: BX = 0007h\n        MOV     AL, [BX]                ; bang[5] = 'F'\n        MOV     kq, AL\n        MOV     AL, [DI+1]              ; bang[1] = 'B'\n        MOV     kq+1, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "MOV SI, OFFSET bang (BE 02 00, 4 chu kỳ) và LEA DI, bang (8D 3E 02 00, 8 chu kỳ) cho cùng 0002h. LEA BX, [BX+SI+2] cộng thanh ghi lúc chạy: BX = 3 + 2 + 2 = 0007h mà không đọc ô nhớ nào (chỉ 13 chu kỳ: 2 + EA 11). Đoán trước: sau LEA BX, [BX+SI+2], BX bằng bao nhiêu? Đáp án 0007h."}, {"label": "Ví dụ: XLAT tra bảng chữ số hệ 16", "code": "; Ví dụ 4: XLAT tra bảng đổi số 0…15 thành chữ số hệ 16\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nhexTab  DB      '0123456789ABCDEF'\nso      DB      1, 10, 15, 0\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, OFFSET hexTab       ; XLAT: AL = DS:[BX + AL]\n        MOV     SI, OFFSET so\n        MOV     CX, 4\nlap:\n        MOV     AL, [SI]\n        XLAT                            ; 1 byte, 11 chu kỳ\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        INC     SI\n        LOOP    lap\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Mỗi vòng: MOV AL, [SI] lấy số 0…15, XLAT đổi thành ký tự ở hexTab[AL], INT 21h hàm 02h in ra. Màn hình hiện 1AF0. Đoán trước: ở vòng 2, sau XLAT, AL bằng bao nhiêu? Đáp án 41h ('A')."}, {"label": "Bẫy: chỉ số vượt cuối bảng", "code": "; Bẫy: chỉ số vượt cuối bảng, đọc trúng biến kế tiếp\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndiem    DB      7, 9, 6, 8, 10          ; 5 phần tử: chỉ số 0…4\ndem     DB      3                       ; biến khác nằm ngay sau bảng\nkq      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, 5                   ; chỉ số 5: ngoài bảng\n        MOV     AL, diem[SI]            ; CPU không kiểm biên: đọc dem\n        MOV     kq, AL                  ; kq = 3, không có thông báo lỗi\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: chỉ số 5 nằm ngoài bảng 5 phần tử (0…4). EA = 0005h là biến dem, nên kq = 3. CPU không báo lỗi, trình dịch cũng không. Đoán trước: AL sau lệnh đọc là bao nhiêu? Đáp án 03h."}, {"label": "Ví dụ: bảng 2 chiều, phần tử (r, c)", "code": "; Ví dụ 6: bảng 3 hàng × 4 cột, phần tử (r, c) ở r × 4 + c\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbang    DB      11H, 12H, 13H, 14H      ; hàng 0\n        DB      21H, 22H, 23H, 24H      ; hàng 1\n        DB      31H, 32H, 33H, 34H      ; hàng 2\nkq      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     BX, 2                   ; hàng r = 2\n        ADD     BX, BX                  ; 2r\n        ADD     BX, BX                  ; 4r = 8: đầu hàng 2\n        MOV     SI, 1                   ; cột c = 1\n        MOV     AL, bang[BX][SI]        ; EA = OFFSET bang + 8 + 1 → 32h\n        MOV     kq, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Hai lệnh ADD BX, BX (3 chu kỳ mỗi lệnh) tính 4r = 8. bang[BX][SI] là dạng cơ sở + chỉ số + độ dời (8A 80 00 00, 8 + EA 11 = 19 chu kỳ). Đoán trước: kq bằng bao nhiêu? Đáp án 32h (hàng 2, cột 1)."}, {"label": "Lỗi: thiếu OFFSET khi nạp con trỏ", "code": "; Lỗi: thiếu OFFSET, con trỏ nhận nội dung thay vì địa chỉ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbang    DW      0010H, 0020H, 0030H\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, bang                ; LỖI: SI = 0010h (nội dung bang[0])\n        MOV     AX, [SI+2]              ; đọc DS:0012h, không phải bang[1]\n        MOV     kq, AX\n; Sửa: MOV SI, OFFSET bang (hoặc LEA SI, bang)\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi logic có chủ đích: MOV SI, bang (8B 36 00 00) đọc nội dung 0010h vào SI. [SI+2] trỏ tới DS:0012h, ngoài bảng (trình mô phỏng: 00h), nên kq = 0000h thay vì 0020h. Sửa: MOV SI, OFFSET bang. Đoán trước: sau lệnh đầu, SI bằng bao nhiêu? Đáp án 0010h."}];
const sim12=makeX86Sim(document.getElementById("x86-l12"),{id:"s12",presets:P12,file:"BAI12.ASM"});
makeX86Ex(document.getElementById("ex-l12"),sim12,[{"t": "Mã LED 7 đoạn", "d": "Bảng ma7 (10 byte) chứa mã LED 7 đoạn của các chữ số 0–9 (quy ước giả định: bit 0 = đoạn a … bit 6 = đoạn g, đoạn sáng = 1). Đọc một phím chữ số bằng INT 21h hàm 08h và ghi mã của chữ số đó vào biến led. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: chữ số → mã LED 7 đoạn bằng bảng tra\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nma7     DB      3FH, 06H, 5BH, 4FH, 66H ; mã 7 đoạn của 0…4\n        DB      6DH, 7DH, 07H, 7FH, 6FH ; 5…9\nled     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím chữ số\n        INT     21H\n; Viết code ở đây: led = ma7[chữ số]\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "9", "mem": [{"at": "led", "bytes": [111]}]}, {"in": "0", "mem": [{"at": "led", "bytes": [63]}]}, {"in": "5", "mem": [{"at": "led", "bytes": [109]}]}, {"in": "1", "mem": [{"at": "led", "bytes": [6]}]}, {"in": "7", "mem": [{"at": "led", "bytes": [7]}]}, {"in": "8", "mem": [{"at": "led", "bytes": [127]}]}]}, {"t": "Phần tử word và địa chỉ của nó", "d": "Bảng gia có 8 phần tử word (chỉ số 0–7), bắt đầu ở độ lệch 0004h sau hai biến kq, pkq. Đọc một phím chữ số i (0–7). Ghi giá trị gia[i] vào kq và địa chỉ (offset) của gia[i] vào pkq. Giữ nguyên phần .DATA. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: phần tử thứ i của bảng word và địa chỉ của nó\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?                       ; giá trị phần tử\npkq     DW      ?                       ; địa chỉ (offset) phần tử\ngia     DW      1200, 850, 3000, 75     ; từ 0004h\n        DW      640, 9999, 15, 4321\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc chỉ số i (0…7)\n        INT     21H\n; Viết code ở đây: kq = gia[i], pkq = địa chỉ của gia[i]\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "5", "mem": [{"at": "kq", "bytes": [15, 39]}, {"at": "pkq", "bytes": [14, 0]}]}, {"in": "0", "mem": [{"at": "kq", "bytes": [176, 4]}, {"at": "pkq", "bytes": [4, 0]}]}, {"in": "7", "mem": [{"at": "kq", "bytes": [225, 16]}, {"at": "pkq", "bytes": [18, 0]}]}, {"in": "3", "mem": [{"at": "kq", "bytes": [75, 0]}, {"at": "pkq", "bytes": [10, 0]}]}, {"in": "1", "mem": [{"at": "kq", "bytes": [82, 3]}, {"at": "pkq", "bytes": [6, 0]}]}, {"in": "6", "mem": [{"at": "kq", "bytes": [15, 0]}, {"at": "pkq", "bytes": [16, 0]}]}]}, {"t": "Đổi 6 phím qua bảng nhanh hơn", "d": "Đọc lần lượt 6 phím chữ số bằng INT 21h hàm 08h (đặt lại AH = 08h trước mỗi lần gọi, không giả định AH còn giữ sau INT 21h: trang chấm có test đổi AH sau mỗi lần đọc phím, bài không nạp lại AH sẽ sai). Ghi mã LED của phím thứ k vào ra[k] (k = 0…5), dùng bảng ma7 như bài 1. Code mẫu cho kết quả đúng nhưng chậm. Viết lại để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: đổi 6 phím chữ số thành 6 mã LED\n; Bản này đúng nhưng chậm: mỗi vòng trừ '0', mở rộng\n; sang SI và dùng địa chỉ có độ dời 16 bit. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nra      DB      6 DUP(0)                ; 6 mã LED\nma7     DB      3FH, 06H, 5BH, 4FH, 66H ; mã 7 đoạn của 0…4\n        DB      6DH, 7DH, 07H, 7FH, 6FH ; 5…9\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DI, 0\n        MOV     CX, 6\nlap:\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     AH, 0\n        MOV     SI, AX\n        MOV     AL, ma7[SI]\n        MOV     ra[DI], AL\n        INC     DI\n        LOOP    lap\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "905127", "mem": [{"at": "ra", "bytes": [111, 63, 109, 6, 91, 7]}]}, {"in": "000000", "ahAfterKey": 0, "mem": [{"at": "ra", "bytes": [63, 63, 63, 63, 63, 63]}]}, {"in": "999999", "mem": [{"at": "ra", "bytes": [111, 111, 111, 111, 111, 111]}]}, {"in": "123456", "mem": [{"at": "ra", "bytes": [6, 91, 79, 102, 109, 125]}]}, {"in": "888880", "mem": [{"at": "ra", "bytes": [127, 127, 127, 127, 127, 63]}]}, {"in": "314159", "ahAfterKey": 76, "mem": [{"at": "ra", "bytes": [79, 6, 102, 6, 109, 111]}]}], "perf": {"cycles": 665, "bytes": 36}}]);

makeQuiz("quiz12","score12",[{"q": "Bảng <code>bangW DW 10h, 20h, 30h, 40h<\/code> bắt đầu ở DS:0100h. Phần tử chỉ số 3 (giá trị 40h) nằm ở độ lệch nào?", "o": ["0106h", "0103h", "0104h", "0108h"], "a": 0, "e": "Mỗi phần tử word 2 byte: 0100h + 3 × 2 = 0106h. 0103h là lỗi quên nhân 2; 0108h là ô ngay sau bảng."}, {"q": "<code>hexTab DB '0123456789ABCDEF'<\/code>. Sau đoạn code sau, AL bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     BX, OFFSET hexTab\n        MOV     AL, 0CH\n        XLAT<\/pre>", "o": ["0Ch, vì XLAT không đổi AL", "42h, vì bảng đếm từ phần tử 1", "30h, vì XLAT luôn đọc byte đầu bảng", "43h, mã ASCII của 'C'"], "a": 3, "e": "XLAT đọc DS:[BX + AL] = hexTab[12] = 'C' = 43h. Chỉ số tính từ 0 như mọi bảng (Ví dụ 4)."}, {"q": "BX = 0100h, DI = 0020h. Lệnh <code>LEA SI, [BX+DI+4]<\/code> làm gì?", "o": ["SI = word đọc từ ô DS:0124h", "SI = 0124h; không đọc ô nhớ nào", "SI = 0124h rồi đọc thêm word ở đó", "Lỗi dịch: LEA chỉ nhận tên biến"], "a": 1, "e": "LEA tính địa chỉ hiệu dụng và đưa vào thanh ghi; nó không truy cập bộ nhớ. MOV SI, [BX+DI+4] mới đọc word ở DS:0124h (Ví dụ 3)."}, {"q": "<code>bang DW 0010h, 0020h<\/code> ở DS:0000h. Học viên viết <code>MOV SI, bang<\/code> thay cho <code>MOV SI, OFFSET bang<\/code>. Điều gì xảy ra?", "o": ["Trình dịch báo lỗi vì SI không nhận tên biến", "Hai cách giống nhau vì bang ở độ lệch 0", "SI = 0000h vì trình dịch tự thêm OFFSET", "SI = 0010h (nội dung), mọi truy cập [SI] lệch khỏi bảng"], "a": 3, "e": "Không có OFFSET, tên biến là toán hạng bộ nhớ: SI nhận word đầu bảng (0010h). Kích thước khớp (word – word) nên trình dịch không báo gì (Ví dụ 7)."}, {"q": "<code>diem DB 7, 9, 6, 8, 10<\/code> và ngay sau là <code>dem DB 3<\/code>. Sau <code>MOV SI, 5<\/code> / <code>MOV AL, diem[SI]<\/code>, AL bằng bao nhiêu?", "o": ["CPU dừng chương trình vì chỉ số vượt biên", "3: chỉ số 5 rơi vào biến dem, không có lỗi", "0: ô ngoài bảng luôn đọc ra 0", "Trình dịch báo lỗi vì 5 lớn hơn số phần tử"], "a": 1, "e": "8086 không kiểm biên; EA = OFFSET diem + 5 là địa chỉ của dem. Chương trình phải tự kiểm tra chỉ số (Ví dụ 5)."}]);

